#' Evaluate the piecewise linear upper envelope at points x
#' @param logf Vector of log-density values at nodes
#' @param x Vector of node coordinates
#' @param vals Vector of evaluation points
#' @return Log-density values on the upper envelope
#' @noRd
eval_upper_envelope <- function(logf, x, vals) {
  n <- length(x)
  if (n == 1) return(rep(logf[1], length(vals)))
  result <- rep(-Inf, length(vals))
  for (i in 1:(n - 1)) {
    # Linear interpolation between node i and i+1
    seg <- x[i] + (x[i + 1] - x[i]) * (vals - x[i]) / (x[n] - x[1])
    # Correct: properly segment each point
    mask <- (vals >= x[i]) & (vals <= x[i + 1])
    if (any(mask)) {
      t <- (vals[mask] - x[i]) / (x[i + 1] - x[i])
      result[mask] <- (1 - t) * logf[i] + t * logf[i + 1]
    }
  }
  result
}

#' Sample from the piecewise linear upper envelope
#' Uses composition-rejection: select a segment with probability proportional
#' to its area, then sample uniformly within the segment.
#' @param logf Vector of log-density values at nodes
#' @param x Vector of node coordinates
#' @param n Number of samples to draw
#' @param rng Random number generator function
#' @return Sample values from the upper envelope
#' @noRd
sample_upper_envelope <- function(logf, x, n, rng) {
  n_nodes <- length(x)
  if (n_nodes == 1) return(rep(x[1], n))
  # Compute area of each trapezoid
  areas <- 0.5 * (x[-1] - x[-n_nodes]) * (exp(logf[-1]) + exp(logf[-n_nodes]))
  total_area <- sum(areas)
  probs <- areas / total_area
  # Select segments
  seg_idx <- sample.int(n_nodes - 1, n, replace = TRUE, prob = probs)
  # Sample uniformly within each selected segment
  u <- rng(n)
  result <- x[seg_idx] + u * (x[seg_idx + 1] - x[seg_idx])
  result
