  log_u <- log(rng(n))
  # Accept where log_u <= log_true - log_env... need envelope values
  # Let's recompute properly
  accepted <- c()
  remaining <- x_upper
  log_true_all <- fun(remaining)
  while (length(accepted) < n && length(remaining) > 0) {
    log_u <- log(rng(length(remaining)))
    accept <- log_u <= log_true_all
    accepted <- c(accepted, remaining[accept])
    remaining <- remaining[!accept]
