  # Ensure init_pts are strictly within bounds
  init_pts <- init_pts[init_pts > xlower & init_pts < xupper]
  if (length(init_pts) < 3) {
    stop("Not enough init_pts within the domain (xlower, xupper)")
  }
  init_pts <- sort(unique(init_pts))

  # Evaluate log-density at initial points
  logf_init <- check_logfun(logfun, init_pts)
  if (any(!is.finite(logf_init))) {
    stop("logfun returned non-finite values at initial points")
  }

  # Check log-concavity at initialization
  concavity_check <- check_logconcavity(logf_init, init_pts)
  if (length(concavity_check) > 0 && any(concavity_check > 1e-10)) {
    stop("Log-density appears non-concave at initial points. ",
         "ARS requires a log-concave density.")
  }

  # --- Main sampling loop ---
  x_nodes <- init_pts
  logf_nodes <- logf_init
  samples <- numeric(n)
  iter <- 0

  for (i in 1:n) {
    # Sample from the current upper envelope
    x_proposed <- sample_upper_envelope(logf_nodes, x_nodes, 1, rng)
    iter <- iter + 1
    if (iter > max_iter) {
      stop(paste0("Exceeded max_iter=", max_iter, " without completing sampling"))
    }

    # Evaluate true log-density at proposed point
    log_true <- logfun(x_proposed)
    if (!is.finite(log_true) || log_true == -Inf) {
      # Point is effectively outside support; reject and resample
      x_nodes <- sort(c(x_nodes, x_proposed))
      logf_nodes <- check_logfun(logfun, x_nodes)
      concavity_check <- check_logconcavity(logf_nodes, x_nodes)
      if (length(concavity_check) > 0 && any(concavity_check > 1e-10)) {
        stop("Log-concavity violated during sampling. ",
             "The target density is not log-concave.")
      }
      x_proposed <- sample_upper_envelope(logf_nodes, x_nodes, 1, rng)
      log_true <- logfun(x_proposed)
    }

    # Compute envelope log-density at proposed point
    log_env <- eval_upper_envelope(logf_nodes, x_nodes, x_proposed)

    # Acceptance step: u <= exp(log_true - log_env)
    u <- rng(1)
    log_u <- log(u)
    if (log_u <= log_true - log_env) {
      # Accept
      samples[i] <- x_proposed
      # Add accepted point to the hull
      x_nodes <- sort(c(x_nodes, x_proposed))
      logf_nodes <- check_logfun(logfun, x_nodes)
      # Check log-concavity after adding point
      concavity_check <- check_logconcavity(logf_nodes, x_nodes)
      if (length(concavity_check) > 0 && any(concavity_check > 1e-10)) {
        stop("Log-concavity violated during sampling. ",
             "The target density is not log-concave.")
      }
    } else {
      # Reject: add the proposed point to the hull (it lies below the envelope)
      x_nodes <- sort(c(x_nodes, x_proposed))
      logf_nodes <- check_logfun(logfun, x_nodes)
      # Check log-concavity after adding point
      concavity_check <- check_logconcavity(logf_nodes, x_nodes)
      if (length(concavity_check) > 0 && any(concavity_check > 1e-10)) {
        stop("Log-concavity violated during sampling. ",
             "The target density is not log-concave.")
      }
      # Decrement counter since we didn't get a sample
      i <- i - 1
    }

    if (i %% 1000 == 0 && i > 0) {
      message(paste("Generated", i, "of", n, "samples"))
    }
  }

  samples
}
