# Implements sampling from log-concave unnormalized density functions
# using piecewise linear log-density approximation.

#' Validate the log-density function by evaluating at sample points
#' @param fun A function returning log-density values
#' @param x Vector of evaluation points
#' @return The log-density values
#' @noRd
check_logfun <- function(fun, x) {
  if (!is.function(fun)) {
    stop("fun must be a function")
  }
  y <- tryCatch(fun(x), error = function(e) NULL)
  if (is.null(y)) {
    stop("fun returned NULL for given x")
  }
  if (!is.numeric(y)) {
    stop("fun must return numeric values")
  }
  if (length(y) != length(x)) {
    stop("fun must return one value per input point")
  }
  y
}

#' Check that the log-density is concave at the current nodes
#' For a concave function, the differences of successive slopes
#' should be <= 0 (slopes are non-increasing).
#' @param logf Vector of log-density values at nodes
#' @param x Vector of node coordinates
#' @return Vector of second differences (should be <= 0 for concave)
#' @noRd
check_logconcavity <- function(logf, x) {
  if (length(x) < 3) return(numeric(0))
  # Compute slopes between consecutive nodes
  slopes <- diff(logf) / diff(x)
  # Second differences of logf (should be <= 0 for concave)
  # Using: f'' ≈ 2*(f[i+1] - f[i])/(x[i+1]-x[i]) - 2*(f[i]-f[i-1])/(x[i]-x[i-1])
  # Simplified: check that slopes are non-increasing
  diff(slopes)
}

#' Evaluate the piecewise linear upper envelope at points vals
#' The upper envelope is the linear interpolation of log(f) at the nodes.
#' @param logf Vector of log-density values at nodes
#' @param x Vector of node coordinates
#' @param vals Vector of evaluation points
#' @return Log-density values on the upper envelope
#' @noRd
eval_upper_envelope <- function(logf, x, vals) {
  n <- length(x)
  if (n == 1) return(rep(logf[1], length(vals)))
  if (n == 2) {
    t <- (vals - x[1]) / (x[2] - x[1])
    return((1 - t) * logf[1] + t * logf[2])
  }
  result <- rep(-Inf, length(vals))
  for (i in 1:(n - 1)) {
    mask <- (vals >= x[i]) & (vals <= x[i + 1])
    if (any(mask)) {
      t <- (vals[mask] - x[i]) / (x[i + 1] - x[i])
      result[mask] <- (1 - t) * logf[i] + t * logf[i + 1]
    }
  }
  result
}

#' Sample from the piecewise linear upper envelope
#' Uses composition-rejection: select a segment with probability proportional
#' to its area under exp(log envelope), then sample uniformly within the segment.
#' @param logf Vector of log-density values at nodes
#' @param x Vector of node coordinates
#' @param n Number of samples to draw
#' @param rng Random number generator function
#' @return Sample values from the upper envelope
#' @noRd
sample_upper_envelope <- function(logf, x, n, rng) {
  n_nodes <- length(x)
  if (n_nodes == 1) return(rep(x[1], n))
  # Compute area of each trapezoid under exp(log envelope)
  # Area_i = (x[i+1] - x[i]) * (exp(logf[i]) + exp(logf[i+1])) / 2
  widths <- diff(x)
  exp_logf <- exp(logf)
  areas <- widths * (exp_logf[-n_nodes] + exp_logf[-1]) / 2
  total_area <- sum(areas)
  probs <- areas / total_area
  # Select segments
  seg_idx <- sample.int(n_nodes - 1, n, replace = TRUE, prob = probs)
  # Sample uniformly within each selected segment
  u <- rng(n)
  result <- x[seg_idx] + u * (x[seg_idx + 1] - x[seg_idx])
  result
}

#' Main Adaptive Rejection Sampler
#'
#' @param n Number of samples to generate (positive integer)
#' @param logfun Function returning log(unnormalized density) - must be vectorized
#' @param xlower Lower bound of support (finite number)
#' @param xupper Upper bound of support (finite number, > xlower)
#' @param init_pts Initial design points (optional; at least 3, auto-generated if NULL)
#' @param rng Random number generator function (default: runif)
#' @param max_iter Maximum iterations (default: 100000)
#' @return Vector of n samples from the target distribution
#' @export
ars <- function(n, logfun, xlower = -Inf, xupper = Inf, init_pts = NULL,
                rng = runif, max_iter = 100000) {
  # --- Input validation ---
  if (!is.numeric(n) || length(n) != 1 || n <= 0 || !is.finite(n) ||
      floor(n) != n) {
    stop("n must be a positive integer")
  }
  if (!is.function(logfun)) {
    stop("logfun must be a function")
  }
  if (!is.numeric(xlower) || length(xlower) != 1 || !is.finite(xlower)) {
    stop("xlower must be a finite number")
  }
  if (!is.numeric(xupper) || length(xupper) != 1 || !is.finite(xupper)) {
    stop("xupper must be a finite number")
  }
  if (xlower >= xupper) {
    stop("xlower must be strictly less than xupper")
  }
  if (!is.function(rng)) {
    stop("rng must be a function")
  }
  if (!is.numeric(max_iter) || length(max_iter) != 1 || max_iter <= 0) {
    stop("max_iter must be a positive number")
  }

  # --- Initialize design points ---
  if (is.null(init_pts)) {
    # Choose initial points spread across the domain, avoiding boundaries
    mid <- (xlower + xupper) / 2
    spread <- (xupper - xlower) / 4
    init_pts <- c(mid - spread, mid, mid + spread)
  }
  if (length(init_pts) < 3) {
    stop("init_pts must contain at least 3 points")
  }
  # Ensure init_pts are strictly within bounds
  init_pts <- init_pts[init_pts > xlower & init_pts < xupper]
  if (length(init_pts) < 3) {
    stop("Not enough init_pts within the domain (xlower, xupper)")
  }
  init_pts <- sort(unique(init_pts))

  # Evaluate log-density at initial points
  logf_init <- check_logfun(logfun, init_pts)
  if (any(!is.finite(logf_init))) {
    stop("logfun returned non-finite values at initial points")
  }

  # Check log-concavity at initialization
  concavity_check <- check_logconcavity(logf_init, init_pts)
  if (length(concavity_check) > 0 && any(concavity_check > 1e-10)) {
    stop("Log-density appears non-concave at initial points. ",
         "ARS requires a log-concave density.")
  }

  # --- Main sampling loop ---
  x_nodes <- init_pts
  logf_nodes <- logf_init
  samples <- numeric(n)
  iter <- 0

  for (i in 1:n) {
    # Sample from the current upper envelope
    x_proposed <- sample_upper_envelope(logf_nodes, x_nodes, 1, rng)
    iter <- iter + 1
    if (iter > max_iter) {
      stop(paste0("Exceeded max_iter=", max_iter, " without completing sampling"))
    }

    # Evaluate true log-density at proposed point
    log_true <- logfun(x_proposed)
    if (!is.finite(log_true) || log_true == -Inf) {
      # Point is effectively outside support; reject and resample
      x_nodes <- sort(c(x_nodes, x_proposed))
      logf_nodes <- check_logfun(logfun, x_nodes)
      concavity_check <- check_logconcavity(logf_nodes, x_nodes)
      if (length(concavity_check) > 0 && any(concavity_check > 1e-10)) {
        stop("Log-concavity violated during sampling. ",
             "The target density is not log-concave.")
      }
      x_proposed <- sample_upper_envelope(logf_nodes, x_nodes, 1, rng)
      log_true <- logfun(x_proposed)
    }

    # Compute envelope log-density at proposed point
    log_env <- eval_upper_envelope(logf_nodes, x_nodes, x_proposed)

    # Acceptance step: u <= exp(log_true - log_env)
    u <- rng(1)
    log_u <- log(u)
    if (log_u <= log_true - log_env) {
      # Accept
      samples[i] <- x_proposed
      # Add accepted point to the hull
      x_nodes <- sort(c(x_nodes, x_proposed))
      logf_nodes <- check_logfun(logfun, x_nodes)
      # Check log-concavity after adding point
      concavity_check <- check_logconcavity(logf_nodes, x_nodes)
      if (length(concavity_check) > 0 && any(concavity_check > 1e-10)) {
        stop("Log-concavity violated during sampling. ",
             "The target density is not log-concave.")
      }
    } else {
      # Reject: add the proposed point to the hull (it lies below the envelope)
      x_nodes <- sort(c(x_nodes, x_proposed))
      logf_nodes <- check_logfun(logfun, x_nodes)
      # Check log-concavity after adding point
      concavity_check <- check_logconcavity(logf_nodes, x_nodes)
      if (length(concavity_check) > 0 && any(concavity_check > 1e-10)) {
        stop("Log-concavity violated during sampling. ",
             "The target density is not log-concave.")
      }
      # Decrement counter since we didn't get a sample
      i <- i - 1
    }

    if (i %% 1000 == 0 && i > 0) {
      message(paste("Generated", i, "of", n, "samples"))
    }
  }

  samples
}
"}

